public boolean subsetSumEqualTarget(int[] nums, int target) {
    int n = nums.length;
    boolean[][] dp = new boolean[n + 1][target + 1];
    dp[0][0] = true;
    for (int i = 1; i <= n; i++) {
        for (int s = 0; s <= target; s++) {
            boolean skip = dp[i - 1][s];
            boolean take = s >= nums[i - 1] && dp[i - 1][s - nums[i - 1]];
            dp[i][s] = skip || take;
        }
    }
    return dp[n][target];
}
